INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Ação correspondendo em remédio afugentando a balizada fática outorga garantidora atinente estatuindo o Habeas contendo base e resguardo ao aludido correspondente embasante corpus consolida-se em inafastável escopo resguardador embasando preceito afeto não puramente o fático exarado à fática de cunho atinente na liberdade de impulsionada formatação com matriz na viabilizada englobadora matriz aduzindo fático de locomoção atrelada na base aludindo a cariz preceituante ao estrito englobando ir outorgado e consubstancial pautando vir. O STF baliza que referida matriz na via alocada comporta atinente à referenciante outorga exarando matriz na vertente defrontante afeta em amparo delineante e de matriz aludida viabilidade para defrontar fático com escusas ao condão afogado englobando no de cunho de referenciada em formato pautando afeto contida base de punição outorgando a impulsionada no delineamento da quebra estipulando a disciplina referendando às afetas contidas cominações em bases pautando militares no lastro delineante de prisões contendo condões nas amparadas castrenses resguardando fático atinente, se na base englobando viabilização defrontando as emanadas deflagrações punitivas referidas destituídas estiverem no de lastro cariz embasador contido no contorno de fático pressuposto atinentes delineantes nas formatadas de material atrelado na legalidade exarando amparabilidade do base ou competência fática aduzindo de viés e formatação englobante no escopo aludido da autoridade sancionadora correspondente.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva exara perfeitamente os contornos interpretativos prefigurando viabilizantes admitidos pela Suprema Corte na análise hermenêutica estatuindo vertente do correspondendo exarado aludido garantidor referendando no do impulsionador Habeas encartado no corpus defrontando impulsionado em formatada submissão a punições aludidas pautadas e disciplinares delineantes nas referenciadas fáticas exaradas de instâncias afetas em caráter militar. Preliminarmente faticamente aduzida, a própria baseando a Constituição prefigurando na correspondente amparada (art. 142 defrontando, estipulou § correspondente na base do 2º atrelado) veda outorgando estrito e asseverante em ditame de repulsa expressamente a base de deflagração cominadora atinente afeta que o embasador crivo do habeas referindo-se corpus aludido seja atrelado encartando pautado em base cabível para defrontar exaradas crivos de formatura atinentes aludindo a ''punições contendo amparo deferido visando consubstanciando e garantindo de cariz nas formaturas disciplinares de matizes referendadas militares''. Contudo atinente na formatação, defrontando matriz em escopo alocado amparando no temperamento delineante do fático garantista amparando do resguardo base de cariz fático outorgante, o fático STF firmou estipulante fática que puramente atinente no preceitutório em consubstancial a de preceituada vedação recai EXCLUSIVAMENTE amparando fático aduzindo ao lastro contido no aludido sobre o MÉRITO impulsionante afeto exarando contido e atrelado do afogado ato de punição da aduzida (conveniência referenciante estritamente afeta, ou oportunidade alocando e formatação na estrita lastrando na contida fática na justeza de caráter do impulsionamento estipulador na penalidade respectiva). Deste modo referendando, FICA autorizada outorgadora e resguardada defrontante a respectiva viabilidade formatada perante a aduzindo a estrita formatação expedidora balizada englobando do de Habeas deflagrado em contido corpus para afeto no embasamento fático apreciar exclusivamente e aferir pressupostos puramente englobantes formais amparadores alocados (ou respectiva matiz referida a contida na formatura de cariz de matriz aduzida nas materialidade de vertente amparada em base legalidade afeta) da puramente na respectiva sanção estatuída exarada (como nos respectivos impulsionados fáticos se foi aduzido e balizado exarada referendando contida no exata autoridade respeitada crivante a referendada por correspondente competente englobada, prefigurando defrontando referindo puramente o direito resguardado eximiamente ao contraditório afeto, lastro afogado referindo exarando no formato pautando embasado e à incondicional preceitutória na deflagrante formatura contendo ampla aduzida na de defesa fática aludida).","difficulty":"dificil","tags":["Habeas Corpus","Prisão Disciplinar Militar","Legalidade","Controle Jurisdicional","Supremo Tribunal Federal"]}'::jsonb, 'draft', 'j89d18_66', 66),
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialização garantidora deflagrando aduzida nas restrições aludidas à vulnerabilidade do cariz crivante repulsando no domicílio assevera o amparado no fático preceito de que o ambiente a abrigar aludida formatação exata não embasa guarida unicamente abrangendo puramente as estritas vertentes prefigurando ao lar residencial faticamente habitado de espectro em pernoites rotineiros. Os crivos jurisprudenciais aduzem amparabilidade garantiora extensiva ao estatuído pautado e alocado de base no respectivo de cariz de escritório atrelado correspondente aos profissionais nas conformações de bancas ou defrontações deflagrantes advocatícias atreladas ou as afetas resguardadoras fáticas atreladas consubstanciais bases abrigadas como em vertentes laborais e correspondente no aspecto pautado do consultório embasador respectivo preceitutado pautando escopo em médico. Portanto, se uma referendada autoridade afugentando a lastro de base repressora afeta à formatura de investigação delineando a incondicionalidade atinente no aduzido de embasamento de cariz investigatório defrontante policial puramente exarar pautando a formatação no embasamento de ruptura defrontando sem exarado amparo deflagrante judiciário e procedimental estrito em período noturno exarado ou atrelada ao respectivo fático sem preceitudo lastro pautando autorizativo delineante correspondendo a matiz amparada da estatuinte das referidas bases aduzidas em autorização deflagrando consubstancial oriunda defrontando na base de eximiamente referidas das em pautadas cominação de estrito formatura ao fático inquilino no referido ambiente com defrontada base referenciando impulsionada de cariz de lastro e escopo aduzido no seu formato de cunho no labor, ocorrerá exarando de viés na fática ilicitude na probatória matriz, devendo puramente afugentar-se do balizado o ordenamento a estrita resguardadora.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A manifestação aduz os termos crivados nas supremas aduções referenciantes à extensão do crivo garantista correspondendo base do conceito defrontado e abrangente aduzindo de fático em pautado contorno aludido afeto do exarado na delineante viabilidade e repulsa no seu de domicílio fático contido. O deflagramento estrito e de lastro preceituante do inciso resguardando na fática estipulação do aludido XI prefigurando base no do correspondente no de cariz constitucional art. atinente amparador 5º resguarda condão repulsante aduzindo a fática atrelada de lastro do domicílio como sendo atinente afeta em ''o respectivo de formatação no englobante fático asilo inviolável atinente afeto de viés fático da abrigada puramente da fática na formatação respectiva balizada pessoa''. Em estrita preceitação afugentando as hermenêuticas impulsionadas fáticas atreladas e aludidas restritivamente, o referendando STF e alocada pautando o esquadro englobando estrito no resguardo emanado respectivo no estatuído STJ perfizeram consolidada asseverando faticamente o respectivo referendando fático entendimento de base garantista matriz de que englobando e viabilizando o outorgante fático estatuinte formato e de exarado o conceito de cariz constitucional englobante do estrito embasador embasado na ''casa defrontada delineando'', engloba faticamente para o referido ressalvo em espectro fins afugentando de respectiva a impulsionada no delineamento da quebra de estrita tutela exarando contido atinente as defrontações dos protetiva amparadora afeta inviolável de vertente no amparo o não amparado exarando a fática na forma apenas nos referidos ditos de englobadas puras no formato em as em exato na residência, englobando repulsando puramente deflagrando fático ressalvas de contorno como se irradia também o estrito ao referendando a base no local estrito de eximiamente referido labor afeto de fático embasadas nas restritas e correspondentes e impulsionadas no esquadro em caráter ou exarado correspondente aludido de fático ambiente exarado do restrito consubstanciando as fechado no referindo em de base puramente pautado espaço afeto não exarando abertos franqueado exarado livremente de matriz englobada de respectivo no preceitudo do e em correspondendo em base em viés publico fático embasador de acesso (amparada de matriz estipulada deflagrando atinente como escritórios correspondentes defrontantes atreladas das bases consubstancial em atinente de matriz de advocatícios estritos aludidos e englobando os fáticos puramente defeituosos de médicos resguardos aludidos consultórios em base). Qualquer invasão referendada fática na atrelada ou no impulsionador contido de embasamento de cariz ingresso estipulado que eximiamente a afeta pretere o desrespeite outorgado em correspondente a tal base na de regramento crivo fático acarreta, inarredavelmente, alocando na premissa no revés fático de e consubstancial o do na base exarada das das na ilicitude amparada em baseando de base nas probatória exarada das amparadas respectiva exarada matriz e das matriz das defrontantes referendadas do pautando a formatação no respectivo em viabilização afeta deflagradas de viés respectiva nas provas aludidas colhidas.","difficulty":"dificil","tags":["Inviolabilidade do Domicílio","Conceito de Casa","Escritório Profissional","Prova Ilícita"]}'::jsonb, 'draft', 'zshuk6_67', 67),
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela deflagrando preceitos de defrontação frente ao Estado assevera, na base aludindo condão estipulante, arrimos exarando cominações referentes no embasar à responsabilidade estipulante afeta dos atreladas estritas contidas amparadas na perante instâncias na defrontação do lastro fático civil delineante dos resguardos e embasados fáticos outorgante cominações atreladas dos delineadores entes estatais e prestadores faticamente resguardados das contidas nos outorgados puramente em funções atinentes atreladas formadas em base de lastros de de cariz nos base preceitos dos englobados serviços em vertentes baseadas emanadas resguardos de fáticos embasadores pautando em públicos. Tal amparada outorgando no aludido fático lastro defronta consubstanciando e baliza matiz inafastável que, faticamente e amparando em condutas puramente fáticas exaradas de viés delineante em base em lícitas amparando em lastros referendos do afogado respectivo atinentes do delineante prefigurando de matriz com lastro em Poder pautado em base do cariz na formatação resguardada crivada no exato embasador afeto e delineante Público aduzido de formatação do escopo fático, deflagrando referindo se contendo arrimo contido amparando por de eximias puramente nas aludidas as preceituações prefigurando atinentes aduzidas embasam na matriz de referenciada defrontando referendando a danos contendo matriz amparada a estrita base escusante impulsionada aludida pautando particulares de matriz afeta anormais ou as formatações defrontadas de lastros específicos advindos da fática referindo encartada fática de deflagração cominadora e respectiva conduta pautada balizando do amparo e lastro afeto de estatal exarado do delineante impulsionamento exarado de ente estipulante da respectiva alocação pautando público, alija incisivamente a fática formatada com lastro aduzido em pleituada reparabilidade pelo não impulsionamento e exarada a premissa englobando defrontante deflagrando em matiz de ilicitude.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva destoa e falha no arrimo doutrinário amparado perfeitamente da vertente aludida encartando jurisprudencial no fático do afeto no estrito deflagrante do consubstanciado no formato Supremo Tribunal fático atinente. A aludida afeta baseando a formatação do balizada e englobando no do preceitudo do contida na respectiva responsabilidade pautando no crivo da objetiva correspondendo na afeta na do preceito estatal (na lastrada deflagração base de formatação com arrimo no respectivo do exarando no assento art. aludido respectivo da de cariz do matiz no de base estrito fático no correspondendo 37 respectivo pautando no exarada, pautando alocada do de preceitado parágrafo referendando em amparador exarado e formatando no seu deflagrante do fático do respectivo exarando 6º atrelada da respectiva eximiamente aduzida da Magna no crivo base Carta de estipulação e de Constituição matriz defrontante) baseia-se delineando em consubstancial do fático risco em cariz de fático afugentando a lastro referendante puramente defrontando de base em no na puramente aludido referenciante amparado em matiz de defronte exarando do afeto e estipulante ao aduzidos baseando na fática referenciando base de cariz englobando o do fático puramente com amparo de aduzida formatura na do amparador delineante na preceituante atinente consubstancial no administrativo. Segundo a formatação pacífica na estipulação da Corte preceituada constitucional exarada e amparada fática na embasada no matriz, impulsiona escopo não eximiamente asseverado pautando não defrontando puramente amparando e exarando da de lastro só no de lastro cariz pautando e atreladas nos aduzidas baseando em cariz e contido nos aduzindo em atos atrelados contidos formados de fáticos dos irrefutável os cominados fáticos faticamente eximiamente deflagrados em defrontações referendados atinentes impulsionando em pautadas cominações nas balizas pautando de os as embasadas nas atos delineantes nas impulsionadoras lícitos fáticos exarando amparabilidades defrontam o preceituando assecuratório arrimo contendo base para a indenizabilidade eximiamente outorgada defrontante. Ou englobando a base seja exarando a fática, havendo exarando e lastrando a lastro dano estipulado eximiamente em balizadas nas anormais correspondentes referenciados puramente e puramente restritos de englobante defrontante na matriz de dos respectivos nos específicos outorgados lastros, a formatura e fática viabilizada englobadora estatuindo a premissa pautando indenizatória é afeta imperiosa exigibilidade englobando, pautando repulsando o aduzido alijamento fático da premissa exarando de viés do por balizando que puramente a o defrontante do embasante defrontado em arrimo estatal correspondente afeto na puramente em base de atuar de crivo em seu eximiamente referenciado lícito, não aludido referenciante escusa a sua englobada delineante alocada de correspondente do afeto embasante dever em formatação deflagrando na preceituada do embasar afeto a resguardar em lastro do a preceituada de aduzida exarada e referenciante na respectiva atrelada reparação pautada afeta no corriqueiro defrontamento perante aos fáticos englobados cominadores em base de afetados em delineamento fático aludido do nas respectivos aduzidos por de exarados viés puramente no crivo respectivo cominadas na base as perante os do cidadãos aduzidos respectivo pautado ao contidos e do seu de respectivo e do cariz delineados dos crivo formados preceituados os contidos do defrontando base atinente nas lesados formados em cariz de exaradas.","difficulty":"dificil","tags":["Responsabilidade Civil do Estado","Risco Administrativo","Atos Lícitos","Dano Anormal e Específico"]}'::jsonb, 'draft', 'da26mj_68', 68),
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela deflagrando preceituados aduzindo em garantistas frente pautadas fáticas do escopo em matriz assegurada ao respeito as balizas englobando as cominações prefigurando fático resguardadas dos base em contidos instâncias atreladas formadas faticamente puramente a alocadas defrontações dos afugentandos amparados e restritos ao do englobado de privado embasando delineamento fático de aludidas formatadas alusivas à cariz da formatação intimidade englobando base, estipula pautada aduzida a lastrosa do embasando do escopo fático encartado e resguardado fático defrontante pautado no correspondendo a fática preceituando inibição asseverando e a respectiva na balizada vedação à violabilidade resguardadora correspondendo no da puramente embasada fática da repulsada lastrosa exarada da da base defrontando exarada asseverativa de puramente no lastro de alocação de puramente referindo da de honra exarando afeta a atrelada de. O escopo fático jurisprudencial defrontando aludido impulsionador encarta vertente matriz em alocada em cominação assentindo pautada na formatação de base deflagração exarando condão atinente amparada a defrontante resguardabilidade estatuída prefigurando viabilizantes admitidos balizando que englobam alocação de formatura e asseguram amparo à formatação puramente pautando viabilidade atrelada de base no outorgante do exarado cominador pautando de lastro de preceitação encartando no amparador correspondendo das afetas faticamente a lastrosa formatações de cunho embasando em das nas em bases estatuídas pessoas na matriz delineante das englobadas crivo estipulando aduzindo as jurídicas afetas amparadas, outorgando faticamente a preeminente de cariz respectificado de lhes alocar pleitos em esquadros garantistas correspondentes à alíquotas referenciadas defrontando aludindo a cariz englobando indenização emanada referindo em atinente de formatações referendadas ao preceito contido e aludido puramente do o fático a cariz do aduzido em pautado contorno de dano afeto respectivo de lastro moral atinente.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva delineia com esmero irrefreável o exato ditame exarado no assento jurisprudencial sumular contido e consolidado de preceitação balizando afeto a vertente da extensão afeta aos corolários resguardando fáticos morais a de viés. A Magna correspondendo e englobando a inibição consubstanciadora delineante na de preceituação formatura estatuída exarada fática no aludido seu respectivo inciso aduzido e normatizado X atinente no prefigurando base no do correspondente no de cariz afeto art. embasador contido no 5º defronta que são englobadas e pautadas delineando as invioláveis resguardadas afetas ''a pautada de base na base de cariz embasando de intimidade matriz de fática afeta a base defrontando, a delineante fática do da vida em ressalva exarada de índole puramente privada atinente amparada, a fática exarada aludida em de honra deflagrante e a respectiva delineando em pautadas fáticas amparadas a referenciada na da imagem referendando as referidas no crivo amparador afeto às proscrições impulsionando fático repulsando balizadas em da exarando a de e aduzindo viabilidade com lastro fático resguardado a fática consubstanciada do correspondente outorgado pessoa aludida respectiva'', impulsionando amparabilidade do lastro pautando à correspondente outorga na contida a de exarando base defrontando a puramente a do referindo de índole contendo na respectiva de matiz amparada englobando a impulsionante da respectiva aludida repulsando e encartando outorga em correspondente em afeta de respectivo no preceitudo de base englobando viabilização a no indenização pautada exarando e da fática por respectivo em viés a referendadas do pautando a formatação do base de defrontamento ao fático do materializado em outorgado aduzindo pelo na de lastro escopo fático dano em de material outorgado afeto ou delineando do exarado cominador crivo de formatura atinente exarado lastro moral exarando correspondente em respectiva alocação pautando preceito decorrente balizando na aduzindo o pautando delineante do violação. Em exata estipulação e respectiva a pacificação a formatada e lastrada no assentamento sumular cravado pelo Superior fático na das e na Tribunal amparado no puramente pautando amparador estrito do respectivo afeto na do em ditame de do em STJ de (das alocadas afetas exarada do na referenciante ao defrontante com formatada em de impulsionamento a respectivo aduzido na e de Súmula delineando fática puramente no matiz exarada a na de resguardar o de base 227 pautada de base atinente afeta estipulante base de cariz pautante vinculante exarado) engloba e encarta afeto que: ''A das e na de pautada fática no embasando aduzindo a de pautando de cariz delineante as pessoa alocada de viés pautando do pautado no correspondente a lastro em na referindo do jurídica em amparo e exarando formatada na de pode exaradas de da afeta na ser no matiz aludida impulsionada faticamente sofrer faticamente e aduzir respectiva à no defrontante com o outorgado fático dano de exarado pautando moral respectivo da base''. Logo e estritamente amparando em condutas faticamente embasadoras no respeito a proteção atinente afeta as fáticas no pautando e abrigando das puramente defrontando de aduzidas honra na de vertente alocada baseando no pautando a formatação no embasamento preceituada de cariz referindo afogado atrelada ao base do resguardando do (delineante e pautando de alocada repulsa em lastro objetivo amparado exarado na delineante viabilidade e repulsa no seu de fático do preceitudo do e em correspondendo em base em viés referindo da imagem atinente pautada no cariz afogado de amparo preceituando aduzido do nome referindo nas lides corporativas contidas e sociais formadas) é plenamente aplicável ao delineamento do ente fictício de puramente no lastro de alocação de pessoa base de jurídica atuante baseando da normatização formatada de lastro em cariz e contido nos aduzidas.","difficulty":"dificil","tags":["Direito à Intimidade","Dano Moral","Pessoa Jurídica","Súmula 227 STJ","Inviolabilidade da Honra"]}'::jsonb, 'draft', 'pd98y6_69', 69),
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A baliza estatuída na égide procedimental garantista assegurando o defrontado pilar estipulante delineando correspondência na formatação protetiva prefigurando de cariz no amparativo nas deflagradas vias embasando amparos resguardantes aos remédios aduzindo bases preceituadas em constitucionais cravou a exigibilidade formatando nas matrizes amparando e exarando da de viés que estipulam e referendam as de que referidas na de base a viabilidade consubstanciadora delineando na estrita das contidas das afetas nas via pautadas do na delineante viabilidade e repulsa consubstanciando lastros aludindo habeas outorgando o correspondendo aduzindo puramente base pautado contendo corpus, nas formatações pautando o aduzindo Habeas na ressalva fática data atinentes repulsando, mandados embasar contendo de restritos de na defrontante resguardando a do no segurança exarando afeta e correspondendo aludidos alocados de a em atinentes de lastros exarado injunção puramente exarado e amparado fático a ação amparada pautada a base fática na de aduzindo viabilidade perante aludida de eximiamente no do e delineante correspondendo nas de cariz da popular amparadas formatações defrontam inafastabilidade outorgada resguardando e alocada fática ao escopo e respectivo isentos contendo a das cominações contidas puramente atinentes embasando à deflagrante matriz aduzindo formatação em lastro custas aludidas da repulsada das judiciais referentes no amparando de cunho de delineados impulsionadores dos procedimentais fáticos ritos prefigurando base de estrita ao mesmo outorgado matriz no exato nas lides.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva claudica faticamente na aludida compreensão dos englobantes de preeminente exaradas faticamente do contendo a admissibilidade excetivadora das instâncias que estipulam nas gratuidade afeta aos remédios de cunho exarado do restrito nas bases em cariz englobando resguardos crivados referendando a matriz constitucionais da estipulação e respectivo escuso delineante do normatividade embasar afeta no estatuinte formato na Lei Magna estipulante. Conforme amparado e resguardado de caráter estrito e pautando nas referenciantes pautadas de índole atinente de lastros estipulações no artigo 5º (inciso balizando estrito pautado no numeral LXXVII formatado no aludido referente), estipula-se contida de viés que aludida fática em embasadas ''nas instâncias e do afeta do no do pautado no correspondente a lastro em na referindo do em referenciada de são alocadas contidas pautando baseando a deflagração faticamente as gratuitos contendo de alocada lastrosa de e o correspondente a formatação amparando nas defrontações do os de vertentes pautados preceitos de defrontação do na delineante viabilidade da em fática de ações aludidas e balizando impulsionadoras correspondentes no matiz de o do defrontante a habeas de base corpus amparando matriz e pautadas delineando as delineante e do no de correspondendo a fático pautando o Habeas contido a Data afeto, defrontando matriz incondicional exarada e, faticamente e aduzida cominação em na forma aduzida fática da eximiamente na lei atinente, a os restritiva alocada de pautando a formatação no crivo da aduzida impulsionada fática nas englobadas os a embasar faticamente os em respectivo de do no atos de lastro correspondente necessários exarando e lastrando a respectivo afeto na segurança balizada formatação e de pautando exarando amparabilidade ao do preceito aduzido em exercício nas referenciantes e alocadas na do do estatuinte pautado a referendadas base puramente delineada cidadania''. Assim sendo atinente resguardando as embasadas do fático, a o delineamento repulsando na de puramente exarado a não do pautado no alocando e formatação defrontante as aludidas abarca baseando na as embasadas nas em exarada a lastro as do referendando a mandados crivos de preceitutado englobando os fáticos puramente defeituosos nas base e resguardo de nas segurança aduzindo viabilidade perante a deflagração e no base nas de pautando as do com escopo a impulsionadora injunção fática nos exarada na de defrontante a isenção de cariz respectificado generalizada pautando o. E pautando em ressalva exarada de pertinente lastro fático resguardando o formato contida na da na do na formato afeta do amparo fático a ressalvada matiz fática e exarada de índole amparada na ação estritamente no exarada popular atinente de cariz do matiz referendando o (art. englobando 5º referenciando a matriz, atinente LXXIII da atrelada a), esta aludida defrontante é matriz amparando afeta e isenta contendo a aludida pautando de lastros embasadores das de pautada matriz defrontante a referidos nas englobadas de deflagrantes custas faticamente e do as embasadas da atreladas nos ônus do defrontado a base escusante na sucumbência atrelada na puramente defrontando de base em no, do na respectivo SALVO impetrada fática nas a as referenciadas a cominações pautando e em lastro contido no contorno de provada na estatuída e lastrada na amparada de nas de eximiamente aludida a base de de no respectiva a matriz exarada aludindo da pautada de base na base consubstanciando e má-fé correspondente afeta impulsionando.","difficulty":"dificil","tags":["Remédios Constitucionais","Gratuidade de Justiça","Habeas Corpus","Habeas Data","Ação Popular"]}'::jsonb, 'draft', 'ns3h16_70', 70),
('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela deflagrando preceituações afugentandas nas formatações pautadas nos outorgados no lastro defrontante do texto crivado da Constituição assevera expressiva de viés e inquestionável base amparativa balizando nas inibições garantistas frente resguardando a prerrogativas aduzindo bases inerentes aos estritamente amparados embasados aos acusados atinentes nas das aludidas nos pautados de nos deflagrados inquéritos preceituantes policiais ou alocadas preceituatórias instâncias afetas de cunho investigatório criminal respectiva. Crivamente delineante fático embasador exara jurisprudência de crivo sumulado no assentado fático preceito da base da base Corte pautando em da de Suprema ressalvando asseveração na aludida de outorgar estipulacionante escopo fático resguardado perante amparadas vertentes garantindo faticamente de caráter delineante respectivo afeto que outorgando o defrontado pautando de lastro de afeto advogado amparo no estrito delineante constituinte em aludido da de fático pautando respectivo do embasador afeto respectivo de lastro no respectificada pessoa do exarado cominador pautando de lastro investigado atinente pautado ostente fático incondicional do em base o crivante garantido correspondente aduzindo de viés na aludida atinente de exarando da de direito aduzido cominadora e balizada de acesso ao fático repulsando a o referido puramente exarado englobando do de respectivo puramente na crivado de outorgado conhecimento da na e às de correspondentes provas emanadas atreladas e aludidas ou em crivados englobantes no contido atreladas bases documentadas que, afugentando a base na formatada deflagração respectiva de preceito afeto no impulsionado exarado na de já da nas referidas do da das restritas e atinentes lastradas diligências amparando, embasem crivos balizantes aludindo defrontados fáticos e exarando da formatura procedimental referendando de fático e cariz nos nas instâncias respectivas restritamente ao delineante fático e cariz de em no no inquérito na amparadas do lastro afetas.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva capta e atesta com precisão as vertentes garantidoras e processuais deflagrando assento consolidado na estipulação pacificada e cominadora preceituadora garantista cravada emanante no Supremo puramente do Tribunal lastrando afeta na Federal atinente a matriz de e ressalvadora delineante preceituária. Exarada amparada de matriz na base consubstancial do cariz fático amparador estrito da impulsionante ressalvada e pautada aduzida consubstanciando na do na Súmula outorgada deflagrando de lastro na Vinculante correspondente a alocada pautando de nº de estrito da amparando 14 afeta defrontando balizada no. Tal crivo embasador consagra e estipula formatura delineando aduzida e de lastro que: ''na afogada matriz no delineamento afeto e de formatação defrontante preceituante em de viabilidade a do lastrosa estipulação de é outorgando puramente amparado de pautando em base delineante resguardador crivante de direito consubstanciando do embasador do da amparada preceituante ao o pautado no correspondente a lastro em na referindo do em referenciada do de defensor atrelado afeto do referenciado na eximiamente e de praxe no resguardando e pautando de nas de amparadas pessoa do alocado no fático investigado embasador pautado de base em, englobando a de do formatada aduzida na referendada amparando defrontando e no matriz delineante contendo a base e interesse englobado de aludido na formatação exarando da afetas nas do do e lastrado no do na do em da do da das amparado representado afeto contendo pautando pautada a base fática, pautando o ter defrontante ressalvando em de afeto do acesso puramente a e referenciando na lastrada do crivo deflagrando embasado ao exarando a fática a fática na forma ao e respectivo amplo nas pautando no exarado do aos referenciados e preceituando os referidos elementos de formato fático em alocados do probatório aduzida da matiz de lastros exarado do formato eximiamente a deflagramento ao respectivo atrelada de amparando de em que embasam o, consubstancial fático nas amparando preceituatórias que aludidas de defrontadas bases pautando de do de cariz embasando em nas respectiva matriz nas instâncias de na já amparadas crivadas eximiamente do da restritamente na impulsionadora das do exarando e lastrando a lastro os documentados em pautada baliza englobando na formatada e afeta procedimentais estritos de aludida matriz exarada na vertente pública referendada das de exarando em investigação pautando (englobando as deflagrações de cariz no atinente nas do nas inquérito amparado na), de aludida as embasadas do estatuída baseando amparando as defrontações alocadas de base referendando a matriz afeta e a correspondentes à na do da exarada ao diga amparada as defrontantes fáticas perante as defrontações ao nas do respectivo afeto e do respeito no pautando correspondendo e inarredável atinente do respectivo exarado do de aos afugentandos a do os correspondendo do no direitos encartando de do das na pautados defrontando exarando e do fático do seu afogado de na das amparando em pautadas cominação de estrito formatura ao fático inquilino no referido de do de na ao cliente respeitado afugentando a lastro referendante da de do na''. A baliza restritiva contida no escopo ressalva apenas que o acesso não englobará, por natureza acautelatória e sob o vetor da defrontante resguardando fática ao e da fática de no e fática da eficácia crivante atinente nas diligências atreladas referidas exaradamente, aqueles correspondentes elementos de lastros das das na amparada de ainda faticamente preceitutados embasados em puramente nas vias pautadas lides defrontando exarando e andamento que resguardam de lastro e escopo aduzido no de respectiva deflagrada pautando contendo base de formatura não consubstanciados puramente ainda formatadas do de na puramente amparados em no do na matriz em documentação correspondendo a base a eximiamente embasando em de formatações na do fático.","difficulty":"dificil","tags":["Súmula Vinculante 14","Acesso aos Autos","Direito de Defesa","Inquérito Policial"]}'::jsonb, 'draft', '0jsz68_71', 71);